seen, state = set(), {}
inbox = [("e1","SHP-1","LOADED"),("e2","SHP-1","ARRIVED_HUB"),
         ("e2","SHP-1","ARRIVED_HUB"),("e3","SHP-1","DELIVERED")]
applied = 0
for eid, shp, st in inbox:
    if eid in seen:
        continue
    seen.add(eid); state[shp] = st; applied += 1
print("받은", len(inbox), "건, 반영", applied, "건, 최종", state)
# 받은 4 건, 반영 3 건, 최종 {'SHP-1': 'DELIVERED'}
